import React, { useState } from 'react';
import axios from 'axios';
import './NewsScraper.css';

const NPR_URL = 'https://www.npr.org/sections/news/';

const NewsScraper = () => {
  const [news, setNews] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('');
  const [sortBy, setSortBy] = useState('date');
  const [filterInput, setFilterInput] = useState('');

  const scrapeNews = async () => {
    setLoading(true);
    setError('');
    try {
      const response = await axios.post('http://localhost:5000/api/scrape', { url: NPR_URL });
      setNews(response.data.news);
      setCategoryFilter('');
      setFilterInput('');
    } catch (err) {
      setError('Error scraping the website. Please try again.');
    }
    setLoading(false);
  };

  // Filtering logic: filter by category/subtopic (user input, case-insensitive, partial match)
  const filteredAndSortedNews = news
    .filter(item =>
      categoryFilter === '' ||
      (item.category && item.category.toLowerCase().includes(categoryFilter.toLowerCase()))
    )
    .sort((a, b) => {
      if (sortBy === 'date') {
        return new Date(b.date) - new Date(a.date);
      }
      if (sortBy === 'title') {
        return a.title.localeCompare(b.title);
      }
      if (sortBy === 'relevance' && categoryFilter) {
        const aScore = (itemField(a)).split(categoryFilter.toLowerCase()).length - 1;
        const bScore = (itemField(b)).split(categoryFilter.toLowerCase()).length - 1;
        return bScore - aScore;
      }
      return 0;
    });

  function itemField(item) {
    return (item.category || '').toLowerCase();
  }

  const handleFilter = () => {
    setCategoryFilter(filterInput);
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleFilter();
    }
  };

  return (
    <div className="news-scraper">
      <h2 style={{textAlign: 'center', marginBottom: 24}}>NPR News Scraper</h2>
      <div className="controls">
        <button
          onClick={scrapeNews}
          disabled={loading}
          className="scrape-button"
        >
          {loading ? 'Scraping...' : 'Scrape News'}
        </button>
      </div>

      {news.length > 0 && (
        <div className="filter-input-row">
          <input
            type="text"
            value={filterInput}
            onChange={e => setFilterInput(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Filter by category or subtopic (e.g. politics, world, business)"
            className="filter-input"
            style={{ minWidth: 260 }}
          />
          <button
            className="scrape-button"
            style={{ minWidth: 90 }}
            onClick={handleFilter}
          >
            Filter
          </button>
          <select
            value={sortBy}
            onChange={e => setSortBy(e.target.value)}
            className="sort-select"
            style={{ minWidth: 140 }}
          >
            <option value="date">Sort by Date</option>
            <option value="title">Sort by Title</option>
            <option value="relevance">Sort by Relevance</option>
          </select>
        </div>
      )}

      {error && <div className="error">{error}</div>}

      {loading && (
        <div className="loading">
          <div className="spinner"></div>
          <p>Scraping in progress...</p>
        </div>
      )}

      <div className="news-list">
        {filteredAndSortedNews.length === 0 && news.length > 0 ? (
          <div style={{textAlign: 'center', width: '100%', color: '#888', fontSize: 18, marginTop: 40}}>
            No results found{categoryFilter ? ` for "${categoryFilter}"` : ''}.
          </div>
        ) : (
          filteredAndSortedNews.map((item, index) => (
            <div key={index} className="news-item">
              <h2>{item.title}</h2>
              <div className="news-meta">
                <span>Category: {item.category || 'N/A'}</span>
                <span>Date: {item.date ? new Date(item.date).toLocaleString() : 'No date available'}</span>
                <span>Author: {item.author || 'Unknown'}</span>
                <span>Source: {item.source}</span>
              </div>
              <a href={item.url} target="_blank" rel="noopener noreferrer">
                Read More
              </a>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default NewsScraper;
